/* =========================================================================
 * terrain.js — real ground heights from the Lands Department 5 m DTM
 * (js/terrain_data.js, generated by reference/data/fetch_dtm.py).
 *
 * The campus is cut into a hillside: the sports ground is a sunken terrace at
 * HKPD ≈ 14 m (model y 0), the main block / pool / statue garden stand on the
 * La Salle Road level ≈ 22.5 m (y 8.5 = the ring's 2/F slab), the east games
 * courts ≈ 24 m (y 10), and the ground climbs to ≈ 34 m just north of the pool.
 * Inside the school wall the ground is a set of flat PADS; outside it follows
 * the DTM. Heights below are model y (HKPD − trackHKPD).
 * ========================================================================= */
'use strict';
window.LSC = window.LSC || {};

(function () {
  const D = window.LSC_DTM;
  const TERRACE = 8.5, EAST = 10;

  function decode(g) {
    const bin = atob(g.data), u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    const i16 = new Int16Array(u8.buffer), f = new Float32Array(i16.length);
    for (let i = 0; i < i16.length; i++) f[i] = i16[i] / 10 - D.trackHKPD;
    return { x0: g.x0, z0: g.z0, step: g.step, nx: g.nx, nz: g.nz, h: f,
      x1: g.x0 + (g.nx - 1) * g.step, z1: g.z0 + (g.nz - 1) * g.step };
  }
  const NEAR = decode(D.grids.near), FAR = decode(D.grids.far);
  delete D.grids;

  function bil(G, x, z) {
    let fx = (x - G.x0) / G.step, fz = (z - G.z0) / G.step;
    fx = Math.max(0, Math.min(G.nx - 1.0001, fx)); fz = Math.max(0, Math.min(G.nz - 1.0001, fz));
    const i = Math.floor(fx), j = Math.floor(fz), tx = fx - i, tz = fz - j, n = G.nx, h = G.h;
    const a = h[j * n + i], b = h[j * n + i + 1], c = h[(j + 1) * n + i], d = h[(j + 1) * n + i + 1];
    return (a * (1 - tx) + b * tx) * (1 - tz) + (c * (1 - tx) + d * tx) * tz;
  }
  const inG = (G, x, z) => x >= G.x0 && x <= G.x1 && z >= G.z0 && z <= G.z1;
  /* DTM height (model y) with no campus pads. */
  function raw(x, z) { return inG(NEAR, x, z) ? bil(NEAR, x, z) : bil(FAR, x, z); }

  /* Flat levels inside the school wall (outline from campus.js / satellite). */
  const PADS = [
    { name: 'sports', y: 0, pts: [[-81, 9], [-52, 9], [-52, -4], [20, -4], [20, 8.5], [88, 8.5], [88, 100.5], [-81, 100.5]] },
    { name: 'terrace', y: TERRACE, pts: [[-81, -100], [6, -100], [20.5, -62], [20, -60], [20, -4], [-52, -4], [-52, 9], [-81, 9]] },
    { name: 'east', y: EAST, pts: [[20, -60], [20.5, -62], [84, 8.5], [20, 8.5]] },
  ];
  function inPoly(pts, x, z) {
    let c = false;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const [xi, zi] = pts[i], [xj, zj] = pts[j];
      if ((zi > z) !== (zj > z) && x < (xj - xi) * (z - zi) / (zj - zi) + xi) c = !c;
    }
    return c;
  }
  function padAt(x, z) {
    if (x < -81.5 || x > 88.5 || z < -100.5 || z > 101) return null;
    for (const p of PADS) if (inPoly(p.pts, x, z)) return p;
    return null;
  }
  /* Open-ground height used by walking / flying (buildings are colliders). */
  function ground(x, z) { const p = padAt(x, z); return p ? p.y : raw(x, z); }
  /* Lowest DTM height under a footprint (to seat a building on a slope). */
  function minUnder(x1, z1, x2, z2) {
    let m = Infinity;
    for (let i = 0; i <= 2; i++) for (let j = 0; j <= 2; j++) m = Math.min(m, raw(x1 + (x2 - x1) * i / 2, z1 + (z2 - z1) * j / 2));
    return m;
  }

  /* ---------- meshes ---------- */
  const cLow = new THREE.Color(0xffffff), cVeg = new THREE.Color(0x6f8f58), cRock = new THREE.Color(0xa29d90);
  function tint(c, x, z, y, slope) {
    // built-up lowland keeps the city texture; steep or high ground is wooded hillside
    const veg = Math.min(1, Math.max(0, (y - 40) / 50) + Math.max(0, slope - 0.35) * 2);
    c.copy(cLow).lerp(cVeg, veg);
    if (y > 380 && Math.hypot(x - 430, z + 2565) < 420) c.lerp(cRock, 0.6); // Lion Rock crown
  }
  /* Regular grid mesh over [xa,xb]×[za,zb]; hole = [x1,z1,x2,z2] cells to skip;
     hfn gives the vertex height. */
  function gridMesh(xa, xb, za, zb, st, hfn, hole, opts) {
    const nx = Math.round((xb - xa) / st), nz = Math.round((zb - za) / st);
    const pos = new Float32Array((nx + 1) * (nz + 1) * 3), uv = new Float32Array((nx + 1) * (nz + 1) * 2);
    const col = new Float32Array((nx + 1) * (nz + 1) * 3), c = new THREE.Color();
    for (let j = 0; j <= nz; j++) for (let i = 0; i <= nx; i++) {
      const x = xa + i * st, z = za + j * st, k = j * (nx + 1) + i, y = hfn(x, z, i === 0 || j === 0 || i === nx || j === nz);
      pos[k * 3] = x; pos[k * 3 + 1] = y; pos[k * 3 + 2] = z;
      uv[k * 2] = x / opts.tw; uv[k * 2 + 1] = -z / opts.th;
      const s = Math.hypot(raw(x + 4, z) - raw(x - 4, z), raw(x, z + 4) - raw(x, z - 4)) / 8;
      tint(c, x, z, y, s);
      col[k * 3] = c.r; col[k * 3 + 1] = c.g; col[k * 3 + 2] = c.b;
    }
    const idx = [];
    for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) {
      const cx = xa + (i + 0.5) * st, cz = za + (j + 0.5) * st;
      if (hole && cx > hole[0] && cx < hole[2] && cz > hole[1] && cz < hole[3]) continue;
      const a = j * (nx + 1) + i, b = a + 1, d = a + nx + 1, e = d + 1;
      idx.push(a, d, b, b, d, e);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    g.setAttribute('color', new THREE.BufferAttribute(col, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    return g;
  }

  function build(scene) {
    const M = LSC.Geo.MATS.cityGround;
    const tw = M.tw, th = M.th;
    const nearMat = new THREE.MeshLambertMaterial({ map: M.mat.map, vertexColors: true });
    const farMat = new THREE.MeshLambertMaterial({ map: M.mat.map, vertexColors: true });
    // ground under a pad sits a little below the campus' own paving; next to a
    // lower pad it drops to that level, so the 2.5 m ramp between two terraces
    // hides under the upper terrace's paving instead of standing in front of
    // the retaining wall
    const padded = (x, z) => {
      const p = padAt(x, z);
      if (!p) return raw(x, z);
      let y = p.y;
      for (const [dx, dz] of [[3, 0], [-3, 0], [0, 3], [0, -3], [2.2, 2.2], [-2.2, 2.2], [2.2, -2.2], [-2.2, -2.2]]) {
        const q = padAt(x + dx, z + dz);
        if (q && q.y < y) y = q.y;
      }
      return y - 0.3;
    };
    const CB = [-250, -250, 250, 250];                         // 2.5 m core
    const core = new THREE.Mesh(gridMesh(CB[0], CB[2], CB[1], CB[3], 2.5, padded, null, { tw, th }), nearMat);
    const near = new THREE.Mesh(gridMesh(NEAR.x0, NEAR.x1, NEAR.z0, NEAR.z1, 5, (x, z, edge) => {
      if (!edge) return padded(x, z);
      // outer ring follows the 20 m far mesh edge so the two meet without cracks
      const s = FAR.step, ax = Math.floor(x / s) * s, az = Math.floor(z / s) * s;
      if (x === NEAR.x0 || x === NEAR.x1) { const t = (z - az) / s; return raw(x, az) * (1 - t) + raw(x, az + s) * t; }
      const t = (x - ax) / s; return raw(ax, z) * (1 - t) + raw(ax + s, z) * t;
    }, CB, { tw, th }), nearMat);
    const far = new THREE.Mesh(gridMesh(FAR.x0, FAR.x1, FAR.z0, FAR.z1, FAR.step, (x, z) => raw(x, z),
      [NEAR.x0, NEAR.z0, NEAR.x1, NEAR.z1], { tw: tw * 4, th: th * 4 }), farMat);
    for (const m of [core, near]) { m.receiveShadow = true; m.name = 'terrain'; scene.add(m); }
    far.name = 'terrainFar'; scene.add(far);
    // sea / plain beyond the DTM window
    const base = new THREE.Mesh(new THREE.PlaneGeometry(30000, 30000).rotateX(-Math.PI / 2),
      new THREE.MeshLambertMaterial({ color: 0x8d9290 }));
    base.position.y = -D.trackHKPD - 0.5;
    scene.add(base);
  }

  LSC.Terrain = { raw, ground, padAt, minUnder, build, PADS, TERRACE, EAST, NEAR, FAR,
    inFar: (x, z) => inG(FAR, x, z) };
})();
